import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, map } from 'rxjs';
import { environment } from 'src/environments/environment';
import { EncryptionService } from '../services/encryption.service';

export interface Post {
  id?: string;
  title: string;
  slug?: string;
  excerpt: string;
  content: string;
  category: string;
  category_id?: string;
  category_name?: string;
  author: string;
  author_id?: string;
  featuredImage?: string;
  featured_image?: string;
  tags: string[];
  status: 'draft' | 'published' | 'scheduled' | 'pending' | 'rejected';
  views?: number;
  publishDate: string;
  published_at?: string;
  created_at?: string;
  updated_at?: string;
}

@Injectable({
  providedIn: 'root'
})
export class PostEditor {
  private API = environment.baseUrl;

  constructor(private http: HttpClient, private crypto: EncryptionService) {}


  // Get single post by ID
  getPost(id: string): Observable<Post> {
    return this.http.get<any>(`${this.API}/postEditor/${id}`).pipe(
      map((res: any) => {
        const decrypted = this.crypto.decrypt(res.data);
        return {
          ...res,
          data: decrypted
        };
      })
    );
  }

  // Get all posts
  getAllPosts(): Observable<Post[]> {
    return this.http.get<any>(`${this.API}/postEditor`).pipe(
      map((res: any) => {
        return this.crypto.decrypt(res.data); // no JSON.parse
      })
    );
  }

  // Create new post with FormData
  createPost(formData: FormData): Observable<any> {
  return this.http.post(`${this.API}/postEditor`, formData);
  }

  // Update existing post with FormData
  updatePost(id: string, formData: FormData): Observable<any> {
    return this.http.post(`${this.API}/postEditor/${id}`, formData);
  }

  // Save post (create or update)
  savePost(id: string | null, formData: FormData): Observable<any> {
    if (id) {
      return this.updatePost(id, formData);
    } else {
      return this.createPost(formData);
    }
  }

  // Delete post
  deletePost(id: string): Observable<any> {
    return this.http.delete(`${this.API}/postEditor/${id}`);
  }

  // Get categories
  getCategories(): Observable<any[]> {
    return this.http.get<any>(`${this.API}/categories`)
  }
}
